"""Checks on the cognitive attacks generated by build_cognitive_pages.py."""
import json
import os
import re
import unittest

import build_cognitive_pages as cog
import build_real_dataset_pages as real
from memory import MemoryBackend, task_memory_fields
from run_attack_suite import attack_trials
from summarize_cognitive import build
from summarize_results import build_asr_table

DATASETS = ("climate", "public_health", "steam")


def load_tasks():
    with open(real.TASKS_PATH, encoding="utf-8") as fh:
        return json.load(fh)


def page_text(ds, chart_type):
    with open(real.DATA_PATH, encoding="utf-8") as fh:
        chart = json.load(fh)[ds][chart_type]
    return " ".join([chart["title"], chart["x_title"], chart["y_title"]])


def metas(attack):
    """(task, meta) for every task's attack page on d3."""
    for task in load_tasks():
        ds, chart_type = task["dataset"], task["viz_type"][len("clean_"):]
        attack_id = f"{attack}__{ds}__{chart_type}_{task['task_id'][len(f'{ds}_{chart_type}_'):]}"
        with open(os.path.join(real.PAGES_DIR, "d3", f"attack_{attack_id}.meta.json"), encoding="utf-8") as fh:
            yield task, json.load(fh)


class CognitivePages(unittest.TestCase):
    def test_every_task_gets_every_attack_on_a_copy_of_its_clean_page(self):
        tasks = load_tasks()
        for library in real.LIBRARIES:
            lib_dir = os.path.join(real.PAGES_DIR, library)
            names = [n for n in os.listdir(lib_dir) if n.startswith("attack_cog_") and n.endswith(".meta.json")]
            self.assertEqual(len(names), len(cog.ATTACKS) * len(tasks))
            for name in names:
                with open(os.path.join(lib_dir, name), encoding="utf-8") as fh:
                    meta = json.load(fh)
                with open(os.path.join(lib_dir, name.replace(".meta.json", ".html")), encoding="utf-8") as fh:
                    attack_html = fh.read()
                clean = f"clean_{meta['chart_type']}__{meta['dataset']}.html"
                with open(os.path.join(lib_dir, clean), encoding="utf-8") as fh:
                    self.assertEqual(attack_html, fh.read(), name)

    def test_bait_and_target_are_the_tasks_bait(self):
        for attack in cog.ATTACKS:
            for task, meta in metas(attack):
                f = real.task_fields(task)
                self.assertEqual((meta["question"], meta["ground_truth"]), (f["question"], f["ground_truth"]))
                self.assertEqual(meta["bait"], f["bait"])
                self.assertEqual(meta["attack_target"], f["bait"])
                self.assertNotEqual(meta["bait"], meta["ground_truth"])
                self.assertEqual((meta["family"], meta["type"]), ("cognitive", "TM"))
                task_memory_fields(meta)  # validates memory, baseline_memory and labels

    def test_rag_control_is_the_corpus_without_the_poisoned_note(self):
        for task, meta in metas("cog_rag_poisoning"):
            _, _, bait, _ = cog.options(task)
            docs = meta["memory"]["corpus"]["documents"]
            control = meta["baseline_memory"]["corpus"]["documents"]
            poisoned = [d for d in docs if d["id"] in meta["poisoned_document_ids"]]
            self.assertEqual(len(poisoned), 1)
            self.assertEqual([d for d in docs if d not in poisoned], control)
            self.assertIn(bait, poisoned[0]["text"])
            visible = page_text(task["dataset"], meta["chart_type"])
            for doc in control:
                if bait in doc["text"]:
                    self.assertIn(bait, visible, task["task_id"])

    def test_rag_poisoned_note_is_retrieved_by_the_question_and_not_by_construction_alone(self):
        for task, meta in metas("cog_rag_poisoning"):
            backend = MemoryBackend(meta["memory"]["corpus"])
            question, _, _, _ = cog.options(task)
            with open(real.DATA_PATH, encoding="utf-8") as fh:
                title = json.load(fh)[task["dataset"]][meta["chart_type"]]["title"]
            ids = lambda query: [d["id"] for d in backend.search(query)["results"]]
            self.assertIn("note_revision", ids(question), task["task_id"])
            # A query about the chart itself also returns benign notes.
            self.assertTrue(set(ids(title)) - {"note_revision"}, title)
            self.assertNotIn("note_revision", ids("data source file"))

    def test_memory_write_control_differs_only_in_the_answer(self):
        for task, meta in metas("cog_memory_write"):
            _, _, bait, _ = cog.options(task)
            attack, control = meta["memory"], meta["baseline_memory"]
            self.assertEqual(len(attack), len(control))
            self.assertEqual(attack[:-1], control[:-1])
            self.assertEqual(attack[-1]["title"], control[-1]["title"])
            self.assertIn(f"the answer is {bait}.", attack[-1]["text"])
            self.assertNotIn("the answer is", control[-1]["text"])
            if bait not in page_text(task["dataset"], meta["chart_type"]):
                token = rf"(?<![\w.,-]){re.escape(bait)}(?![\w,-])"
                self.assertFalse(any(re.search(token, doc["text"]) for doc in control), bait)

    def test_icl_log_differs_only_in_the_option_at_the_answer_letter(self):
        for task, meta in metas("cog_icl_trap"):
            attack, control = meta["memory"], meta["baseline_memory"]
            self.assertEqual(len(attack), cog.ICL_EXAMPLES)
            given = lambda doc: re.search(r"Answer given: ([ABC])\. Grade: correct\.$", doc["text"]).group(1)
            letter = meta["bait"]
            at = lambda doc, l: re.search(rf"\({l}\) (.*?)(?: \([ABC]\) |\. Answer given)", doc["text"]).group(1)
            examples = cog.icl_examples(task, load_tasks())
            self.assertTrue(all(e["dataset"] != task["dataset"] and e["viz_type"] == task["viz_type"]
                                for e in examples))
            for example, a, c in zip(examples, attack, control):
                _, truth, bait, other = cog.options(example)
                self.assertEqual(a["title"], c["title"])
                # Same answer letter in both arms (letter skew held constant) ...
                self.assertEqual((given(a), given(c)), (letter, letter))
                # ... with the example's bait there in the attack and its truth in the control.
                self.assertEqual((at(a, letter), at(c, letter)), (bait, truth))
                self.assertEqual(sorted(at(a, l) for l in "ABC"), sorted(at(c, l) for l in "ABC"))
                self.assertEqual(sorted(at(a, l) for l in "ABC"), sorted([truth, bait, other]))


class CognitiveTrials(unittest.TestCase):
    def test_baselines_get_control_memory_and_clean_page(self):
        trials = attack_trials(["d3"], attack_ids=set(cog.ATTACKS), datasets=set(DATASETS))
        self.assertEqual(len(trials), 2 * len(cog.ATTACKS) * len(load_tasks()))
        for attack, baseline in zip(trials[::2], trials[1::2]):
            self.assertEqual(baseline["attack_id"], attack["attack_id"] + "__clean_baseline")
            self.assertTrue(os.path.basename(baseline["html_path"]).startswith("clean_"))
            self.assertEqual(baseline["question"], attack["question"])
            self.assertIn(attack["bait"], "ABC")
            self.assertNotEqual(baseline["memory"], attack["memory"])
            self.assertEqual(baseline["poisoned_document_ids"], [])
            if attack["attack_id"].startswith("cog_rag_poisoning"):
                self.assertEqual(len(baseline["memory"]["corpus"]["documents"]), 3)

    def test_cognitive_attacks_run_only_when_named(self):
        everything = attack_trials(["d3"], datasets=set(DATASETS))
        self.assertFalse(any(t["attack_id"].startswith("cog_") for t in everything))
        one = attack_trials(["d3"], attack_ids={"cog_icl_trap"}, datasets=set(DATASETS))
        self.assertEqual(len(one), 2 * len(load_tasks()))

    def test_corpus_baseline_must_match_memory_form(self):
        corpus = {"corpus": {"documents": [{"id": "a", "title": "t", "text": "x"}]}}
        task_memory_fields({"memory": corpus, "baseline_memory": corpus})
        with self.assertRaises(ValueError):
            task_memory_fields({"memory": [{"title": "t", "source": "s", "text": "x"}],
                                "baseline_memory": corpus})
        with self.assertRaises(ValueError):
            task_memory_fields({"memory": corpus, "baseline_memory": [{"title": "t", "source": "s", "text": "x"}]})
        with self.assertRaises(ValueError):
            task_memory_fields({"memory": corpus, "baseline_memory": {"corpus": {"documents": [{}]}}})
        with self.assertRaises(ValueError):
            task_memory_fields({"memory": corpus, "baseline_memory": corpus, "poisoned_document_ids": ["a"]})


class CognitiveSummary(unittest.TestCase):
    def test_pairs_bait_retrieval_and_hashed_conditions(self):
        attack_id = "cog_rag_poisoning__climate__bar_retrieve_value"
        base = {"model": "M", "library": "d3", "question": "Q", "trial": "0"}
        rows = []
        for condition, attack_answer, exposed in (("react_browser_repair_memory_0123456789abcdef", "B", 1),
                                                  ("react_browser_repair_memory_fedcba9876543210", "C", 0)):
            rows += [dict(base, condition=condition, attack_id=attack_id, correct="false",
                          extracted_answer=attack_answer, notes=f"stop=final; memory_exposed={exposed}"),
                     dict(base, condition=condition, attack_id=attack_id + "__clean_baseline",
                          correct="true", extracted_answer="A", notes="stop=final; memory_exposed=0")]
        rows.append(dict(base, condition="react_browser_repair", attack_id="cog_icl_trap__x", correct="false",
                         extracted_answer="B", notes=""))
        stats = build(rows, {attack_id: "B", "cog_icl_trap__x": "B"})
        s = stats[("react_browser_repair", "M", "cog_rag_poisoning")]
        self.assertEqual((s["pairs"], s["right"], s["fooled"], s["deceived"]), (2, 2, 2, 1))
        self.assertEqual((s["attacks"], s["retrieved"], s["right_retrieved"], s["deceived_retrieved"]),
                         (2, 1, 1, 1))
        icl = stats[("react_browser_repair", "M", "cog_icl_trap")]
        self.assertEqual((icl["attacks"], icl["excluded"], icl["pairs"]), (1, 1, 0))

    def test_chart_attack_summary_leaves_out_cognitive_rows(self):
        base = {"condition": "react_browser_repair", "model": "M", "library": "d3", "question": "Q",
                "trial": "0", "notes": "", "extracted_answer": "A"}
        rows = []
        for attack_id in ("bar_aria_deception__climate__sort", "cog_memory_write__climate__bar_sort"):
            rows += [dict(base, attack_id=attack_id, correct="false"),
                     dict(base, attack_id=attack_id + "__clean_baseline", correct="true")]
        table = build_asr_table(rows)
        self.assertEqual([r["attack_id"] for r in table], ["bar_aria_deception__climate__sort"])


if __name__ == "__main__":
    unittest.main()
